(() => {
  'use strict';
  const root=document.querySelector('#demo-root');
  const modal=document.querySelector('#demo-dialog');
  const modalContent=document.querySelector('#demo-dialog-content');
  const requested=new URLSearchParams(location.search).get('project');
  const project=window.FOLIO.projects.find(p=>p.id===requested)||window.FOLIO.projects[0];
  const key=project.id;
  document.title=`${project.name} — Demo ${project.label} | Folio`;
  document.querySelector('#demo-switch').value=key;
  document.querySelector('#demo-switch').addEventListener('change',e=>{location.search=`?project=${encodeURIComponent(e.target.value)}`;});
  document.body.classList.add(({objects:'objects',orbit:'orbit',journal:'journal',pulse:'dashboard',escape:'travel',moka:'restaurant'})[key]+'-page');
  if(['orbit','journal'].includes(key)) document.body.classList.add(key+'-page');
  const money=n=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(n);
  const safe=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const localDate=(offset=0)=>{const d=new Date();d.setDate(d.getDate()+offset);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
  const nav=(brand,links,action='')=>`<nav class="demo-nav demo-shell" aria-label="Điều hướng demo"><a class="demo-brand" href="?project=${key}">${brand}</a><div class="demo-nav-links">${links.map(([href,label])=>`<a href="${href}">${label}</a>`).join('')}${action}</div></nav>`;
  let toastTimer;
  const toast=message=>{const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2600);};
  const open=html=>{modalContent.innerHTML=html;if(!modal.open)modal.showModal();document.body.classList.add('modal-open');};
  document.querySelector('#close-dialog').addEventListener('click',()=>modal.close());
  modal.addEventListener('close',()=>document.body.classList.remove('modal-open'));
  modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
  const confirmation=(title,text)=>open(`<div class="confirmation"><div class="confirmation-symbol">✓</div><h2 id="demo-dialog-title">${title}</h2><p>${text}</p><p>Đây là thao tác mô phỏng trong portfolio. Không có dữ liệu được gửi đi hoặc giao dịch thực tế.</p><button class="button dark" data-dismiss>Tiếp tục khám phá <span>↗</span></button></div>`);
  modalContent.addEventListener('click',e=>{if(e.target.closest('[data-dismiss]'))modal.close();});
  const categories=(items,attribute)=>`<div class="demo-tabs" role="group" aria-label="Lọc theo chuyên mục">${items.map(([id,label],i)=>`<button data-${attribute}="${id}" class="${i?'':'active'}" aria-pressed="${!i}">${label}</button>`).join('')}</div>`;
  const tabState=(buttons,selected)=>buttons.forEach(button=>{button.classList.toggle('active',button===selected);button.setAttribute('aria-pressed',String(button===selected));});

  // Cửa hàng và thực đơn dùng chung giỏ hàng mẫu, không thanh toán thật.
  const cart=new Map();
  let products=[];
  const cartCount=()=>[...cart.values()].reduce((sum,n)=>sum+n,0);
  const cartTotal=()=>products.reduce((sum,p)=>sum+p.price*(cart.get(p.id)||0),0);
  function updateCartBadge(){document.querySelectorAll('[data-cart-count]').forEach(el=>el.textContent=cartCount());}
  function renderCart(){
    const rows=products.filter(p=>cart.has(p.id));
    open(`<h2 id="demo-dialog-title">${key==='moka'?'Món bạn đã chọn':'Giỏ hàng của bạn'}</h2>${rows.length?rows.map(p=>`<div class="cart-row"><div><h3>${p.name}</h3><p>${money(p.price)}</p></div><div class="quantity-control"><button data-quantity="${p.id}" data-delta="-1" aria-label="Giảm ${p.name}">−</button><span>${cart.get(p.id)}</span><button data-quantity="${p.id}" data-delta="1" aria-label="Tăng ${p.name}">+</button></div></div>`).join('')+`<div class="cart-total"><span>Tổng tạm tính</span><strong>${money(cartTotal())}</strong></div><button class="button dark" data-checkout>Xác nhận đơn mẫu <span>↗</span></button><p class="detail-note">Không thu thập thông tin thanh toán. Không có đơn hàng thực tế.</p>`:'<p class="empty-note">Giỏ của bạn đang trống. Thử thêm một món mà bạn thích nhé.</p><button class="button dark" data-dismiss>Khám phá tiếp <span>↗</span></button>'}`);
  }
  root.addEventListener('click',e=>{
    const add=e.target.closest('[data-add]');
    if(add){const id=add.dataset.add;cart.set(id,(cart.get(id)||0)+1);updateCartBadge();toast(`Đã thêm ${products.find(p=>p.id===id).name}`);}
    if(e.target.closest('[data-cart]'))renderCart();
  });
  modalContent.addEventListener('click',e=>{
    const quantity=e.target.closest('[data-quantity]');
    if(quantity){const id=quantity.dataset.quantity;const count=(cart.get(id)||0)+Number(quantity.dataset.delta);if(count<=0)cart.delete(id);else cart.set(id,count);updateCartBadge();renderCart();}
    if(e.target.closest('[data-checkout]')){const total=cartTotal();cart.clear();updateCartBadge();confirmation('Đơn mẫu đã sẵn sàng.',`Tổng giá trị minh họa: <strong>${money(total)}</strong>. Cảm ơn bạn đã trải nghiệm ${project.name}.`);}
  });

  function objects(){
    products=[
      {id:'chair',name:'Lounge Chair / Sand',price:3250000,group:'seating',image:'chair.jpg',tag:'BESTSELLER'},
      {id:'room',name:'Living Set / Warm',price:8900000,group:'living',image:'interior.jpg',tag:'THE LIVING COLLECTION'},
      {id:'ceramic',name:'Coffee Set / Everyday',price:480000,group:'objects',image:'coffee.jpg',tag:'LITTLE EVERYDAY THINGS'},
      {id:'chair-olive',name:'Lounge Chair / Soft',price:3650000,group:'seating',image:'chair.jpg',tag:'SOFT TEXTURES'},
      {id:'living-edit',name:'Living Edit / Natural',price:7200000,group:'living',image:'interior.jpg',tag:'CONSIDERED DESIGN'},
      {id:'cup',name:'Morning Ritual / Set',price:650000,group:'objects',image:'coffee.jpg',tag:'NEW ARRIVAL'}
    ];
    root.innerHTML=nav('objects.',[['#collection','Bộ sưu tập'],['#story','Câu chuyện']],'<button data-cart class="nav-action">Bag (<span data-cart-count>0</span>)</button>')+`<main id="demo-main"><section class="demo-hero demo-shell"><div><p class="demo-kicker">THOUGHTFUL OBJECTS. EVERYDAY LIVING.</p><h1 class="demo-title">Less, but<br><em>better.</em></h1><p class="demo-lead">Ít đồ hơn, nhiều khoảng thở hơn. Những vật dụng giản đơn, được chọn lọc để sống cùng bạn thật lâu.</p><a class="button dark" href="#collection">Khám phá bộ sưu tập <span>↘</span></a></div><img class="demo-hero-image" src="../assets/chair.jpg" alt="Ghế lounge bọc vải trong bộ sưu tập nội thất" fetchpriority="high"></section><section class="demo-section demo-shell" id="collection"><div class="demo-section-heading"><h2>Objects for your everyday.</h2><p>Sản phẩm và giá chỉ dùng để minh họa.</p></div>${categories([['all','Tất cả'],['seating','Ghế ngồi'],['living','Không gian sống'],['objects','Đồ dùng']],'shop-filter')}<div class="product-grid">${products.map(p=>`<article class="product-card" data-group="${p.group}"><div class="product-image"><img src="../assets/${p.image}" alt="${p.name}" loading="lazy"><span class="product-label">${p.tag}</span></div><div class="product-details"><div><h3>${p.name}</h3><p>${money(p.price)}</p></div><button class="add-product" data-add="${p.id}" aria-label="Thêm ${p.name} vào giỏ">+</button></div></article>`).join('')}</div></section><section class="demo-section demo-shell shop-story" id="story"><img src="../assets/interior.jpg" alt="Phòng khách với màu sắc tự nhiên" loading="lazy"><div><p class="demo-kicker">FEWER THINGS. MORE MEANING.</p><h2>Không gian đẹp.<br><em>Cuộc sống nhẹ hơn.</em></h2><p>Objects là cửa hàng concept dành cho những người yêu vẻ đẹp giản đơn. Chúng mình tin rằng một đồ vật tốt không cần phải gây chú ý — chỉ cần mang lại cảm giác đúng, mỗi ngày.</p></div></section></main>`;
    root.querySelectorAll('[data-shop-filter]').forEach(button=>button.addEventListener('click',()=>{tabState(root.querySelectorAll('[data-shop-filter]'),button);root.querySelectorAll('.product-card').forEach(card=>card.hidden=button.dataset.shopFilter!=='all'&&card.dataset.group!==button.dataset.shopFilter);}));
  }

  function orbit(){
    root.innerHTML=nav('◉ orbit',[['#features','Tính năng'],['#pricing','Bảng giá']],'<a class="nav-action" href="#pricing">Bắt đầu ↗</a>')+`<main id="demo-main"><section class="demo-hero demo-shell"><p class="demo-kicker">LESS BUSYWORK. MORE GREAT WORK.</p><h1 class="demo-title">Big ideas.<br><em>One shared space.</em></h1><p class="demo-lead">Một nơi cho ý tưởng, kế hoạch và những điều bạn đang cùng nhau xây dựng. Ít tab hơn. Nhiều khoảng trống để sáng tạo hơn.</p><a class="orbit-button" href="#pricing">Tìm quỹ đạo của bạn ↗</a><div class="orbit-preview"><div class="orbit-preview-top"><span>◉ orbit / Workspace concept</span><span>Website launch ↗</span></div><div class="kanban">${[['Ý tưởng',['Định hình câu chuyện','Khám phá hướng hình ảnh']],['Đang thực hiện',['Thiết kế trang chủ','Phát triển tương tác']],['Hoàn thành',['Bản phác thảo đầu tiên','Sắp xếp nội dung']]].map(([name,tasks],i)=>`<div class="kanban-column"><h3>● ${name.toUpperCase()}</h3>${tasks.map((task,j)=>`<div class="kanban-card"><span>${['DESIGN','DEVELOPMENT','STRATEGY'][(i+j)%3]}</span>${task}<small>✦ Team space &nbsp; ${i+j+1} ghi chú</small></div>`).join('')}</div>`).join('')}</div></div></section><section class="demo-section demo-shell" id="features"><div class="demo-section-heading"><h2>Make room for great work.</h2><p>Tính năng mô tả cho sản phẩm concept.</p></div><div class="orbit-feature-grid"><article class="orbit-feature"><span>✦</span><h3>Mọi thứ trong tầm nhìn</h3><p>Gom kế hoạch, đầu việc và ghi chú vào một không gian, để ai cũng biết điều gì đang diễn ra.</p></article><article class="orbit-feature"><span>◉</span><h3>Cùng chung một quỹ đạo</h3><p>Trao đổi ngay trong ngữ cảnh công việc. Một nơi cho những phản hồi giúp ý tưởng đi xa hơn.</p></article><article class="orbit-feature"><span>↗</span><h3>Nhịp làm việc của bạn</h3><p>Chọn cách nhìn phù hợp cho từng giai đoạn: từ ý tưởng ban đầu đến kế hoạch đưa sản phẩm ra mắt.</p></article></div></section><section class="demo-section demo-shell" id="pricing"><div class="demo-section-heading"><h2>Find your orbit.</h2><div class="price-toggle" role="group" aria-label="Chu kỳ thanh toán"><button data-billing="month" class="active" aria-pressed="true">Theo tháng</button><button data-billing="year" aria-pressed="false">Theo năm · −20%</button></div></div><div class="price-grid">${[{name:'Solo',price:0,desc:'Một góc làm việc cho những ý tưởng của riêng bạn.',features:['1 không gian cá nhân','3 dự án concept','Ghi chú & quản lý đầu việc']},{name:'Team',price:149000,desc:'Cùng nhau làm ra những điều lớn hơn.',features:['5 thành viên / nhóm','Không giới hạn dự án','Bảng kế hoạch & cộng tác']},{name:'Studio',price:299000,desc:'Một nơi cho những đội ngũ nhiều ý tưởng.',features:['20 thành viên / nhóm','Không gian khách hàng','Báo cáo & phân quyền concept']}].map((p,i)=>`<article class="price-card ${i===1?'featured':''}">${i===1?'<span class="price-badge">THE SWEET SPOT</span>':''}<h3>${p.name}</h3><p>${p.desc}</p><div class="price-amount" data-price="${p.price}">${p.price===0?'0':new Intl.NumberFormat('vi-VN').format(p.price)}<small> ₫ / tháng</small></div><p data-billing-note>Thanh toán hàng tháng · Giá minh họa</p><ul>${p.features.map(f=>`<li>✓ &nbsp; ${f}</li>`).join('')}</ul><button class="orbit-button" data-plan="${p.name}">Khám phá ${p.name} ↗</button></article>`).join('')}</div></section><section class="demo-section demo-shell faq"><div class="demo-section-heading"><h2>A little more clarity.</h2></div><details><summary>Đây có phải một sản phẩm đang hoạt động không?</summary><p>Orbit là landing page concept để minh họa thiết kế website cho sản phẩm SaaS. Bảng công việc và các tính năng mô tả chưa kết nối với một ứng dụng thật.</p></details><details><summary>Bảng giá theo năm được tính như thế nào?</summary><p>Giá tháng được giảm 20% khi chọn chu kỳ năm. Số tiền hiển thị là giá tương đương mỗi tháng; thông tin thanh toán năm được cập nhật bên dưới.</p></details><details><summary>Tôi có thể đăng ký hoặc thanh toán không?</summary><p>Bạn có thể mở trải nghiệm chọn gói mẫu. Website không tạo tài khoản và không nhận thanh toán.</p></details></section></main>`;
    root.querySelectorAll('[data-billing]').forEach(button=>button.addEventListener('click',()=>{
      tabState(root.querySelectorAll('[data-billing]'),button);const year=button.dataset.billing==='year';
      root.querySelectorAll('[data-price]').forEach(el=>{const price=Math.round(Number(el.dataset.price)*(year?.8:1));el.innerHTML=`${new Intl.NumberFormat('vi-VN').format(price)}<small> ₫ / tháng</small>`;el.nextElementSibling.textContent=year?`Thanh toán ${money(price*12)} / năm · Giá minh họa`:'Thanh toán hàng tháng · Giá minh họa';});
    }));
    root.querySelectorAll('[data-plan]').forEach(button=>button.addEventListener('click',()=>confirmation(`Hello, ${button.dataset.plan}.`,'Bạn vừa thử bước chọn gói của Orbit. Một landing page rõ ràng giúp người dùng hiểu sản phẩm và tìm thấy lựa chọn phù hợp.')));
  }

  const articles=[
    {id:'space',category:'design',label:'DESIGN',title:'Khoảng trống cũng là một phần của câu chuyện.',image:'architecture.jpg',time:5,excerpt:'Một góc nhìn về khoảng thở trong thiết kế, và vì sao ít hơn đôi khi lại nói được nhiều hơn.',body:[['Để một khoảng cho điều quan trọng','Khi mọi thứ cùng lên tiếng, ta khó nghe được điều thực sự cần nghe. Trong một giao diện, khoảng trống tạo nên thứ tự: tiêu đề được nhận ra trước, nội dung có chỗ để đọc, hành động có chỗ để xuất hiện.'],['Nhịp điệu của một trang','Hãy thử nhìn trang web như một bản nhạc. Khoảng cách giữa hai phần nội dung là một nhịp nghỉ. Quá dày sẽ vội, quá thưa có thể khiến câu chuyện rời rạc. Độ thoáng đẹp nhất là độ thoáng giúp người đọc đi tiếp tự nhiên.'],['Bắt đầu từ việc bớt đi','Chọn một màn hình bạn đang làm và bỏ đi một đường viền không cần thiết. Tăng khoảng cách quanh điều quan trọng nhất. Đôi khi, thay đổi nhỏ nhất lại khiến tổng thể rõ ràng hơn.']]},
    {id:'morning',category:'living',label:'LIVING',title:'Một buổi sáng không cần phải vội.',image:'coffee.jpg',time:4,excerpt:'Một ly cà phê, một cuốn sổ mở và cách bắt đầu ngày mới bằng một khoảng yên nhỏ.',body:[['Mười phút cho riêng mình','Không cần một nghi thức cầu kỳ. Một chiếc cốc quen, ánh sáng đầu ngày và vài phút chưa mở điện thoại cũng đủ tạo một khoảng chuyển dịu dàng.'],['Ghi lại trước khi quên','Có những ý nghĩ chỉ ghé qua rất nhanh. Ghi một dòng trong sổ không phải để làm thêm việc, mà để cho đầu óc một chỗ đặt xuống.'],['Một nhịp vừa với bạn','Một buổi sáng dễ chịu có thể rất khác nhau với mỗi người. Điều đáng thử là tìm một nhịp khiến mình thấy hiện diện hơn trong ngày của chính mình.']]},
    {id:'home',category:'living',label:'LIVING',title:'Căn phòng kể chuyện về người ở trong nó.',image:'interior.jpg',time:6,excerpt:'Không gian sống không nhất thiết hoàn hảo. Chỉ cần có điều gì đó khiến bạn muốn trở về.',body:[['Những đồ vật có ký ức','Một chiếc ghế đã cũ, bức tranh mua trong chuyến đi, chiếc đèn đọc sách: những món đồ rất riêng thường khiến căn phòng có hồn hơn bất kỳ công thức trang trí nào.'],['Ánh sáng thay đổi mọi thứ','Thử quan sát một góc nhà ở những giờ khác nhau. Ánh sáng buổi sáng và buổi chiều có thể biến cùng một không gian thành hai trải nghiệm khác biệt.'],['Dành chỗ cho cuộc sống','Không gian là để sống trong đó. Một cuốn sách đặt dở, một chiếc cốc trên bàn, những dấu vết rất nhỏ ấy cũng là một phần của vẻ đẹp.']]},
    {id:'journey',category:'stories',label:'STORIES',title:'Đi xa một chút, để nhìn lại gần hơn.',image:'coast.jpg',time:5,excerpt:'Một chuyến đi không cần kín lịch mới trở thành một chuyến đi đáng nhớ.',body:[['Không có gì trong lịch trình','Có những ngày đẹp nhất của chuyến đi bắt đầu bằng việc chưa biết mình sẽ làm gì. Một lối nhỏ, một lời chỉ đường, một chỗ ngồi bên hồ có thể trở thành cả câu chuyện.'],['Nhìn bằng đôi mắt mới','Điều thú vị của việc đến một nơi lạ là ta quan sát kỹ hơn. Màu cửa, nhịp phố, tiếng gió: những thứ từng bị bỏ qua bỗng trở nên rõ ràng.'],['Mang một cách nhìn trở về','Có thể thứ đáng mang về không phải là món quà, mà là cách chú ý. Thử nhìn con đường quen ở nhà bằng sự tò mò của một người vừa đến lần đầu.']]},
    {id:'objects',category:'design',label:'DESIGN',title:'Đồ vật giản đơn, ý nghĩa không giản đơn.',image:'chair.jpg',time:4,excerpt:'Sự chỉn chu thường nằm ở những thứ bạn không nhận ra ngay từ lần nhìn đầu.',body:[['Một đường cong vừa đủ','Một chiếc ghế có thể chỉ có vài đường nét, nhưng mỗi góc nghiêng đều ảnh hưởng đến cách ta ngồi và cảm nhận nó. Thiết kế giản đơn không đồng nghĩa với ít suy nghĩ.'],['Cảm giác trước lời giải thích','Có những thứ khiến ta thấy đúng trước khi biết vì sao. Một bề mặt mịn, một nút bấm vừa tay, một chuyển động nhẹ — tất cả cộng lại thành trải nghiệm.'],['Sử dụng là phần tiếp theo của thiết kế','Đồ vật chỉ thực sự hoàn chỉnh khi đi vào cuộc sống. Những vết dùng cũng là cách nó tiếp tục câu chuyện cùng người sở hữu.']]},
    {id:'table',category:'stories',label:'STORIES',title:'Những cuộc hẹn quanh một chiếc bàn.',image:'food.jpg',time:3,excerpt:'Một bữa ăn ngon đôi khi bắt đầu từ người ngồi ở phía bên kia.',body:[['Chỗ ngồi dành cho một câu chuyện','Một chiếc bàn là một cái cớ rất hay để cùng dừng lại. Có người kể chuyện ngày hôm nay, có người chỉ lắng nghe, và thế là một bữa ăn đã có thêm hương vị.'],['Những điều không có trong thực đơn','Ánh đèn, tiếng nhạc, một cử chỉ thân thiện: trải nghiệm của một quán ăn không chỉ nằm trong món được gọi.'],['Để lại một buổi chiều dễ nhớ','Không phải cuộc hẹn nào cũng cần dịp đặc biệt. Đôi khi một bữa ăn rất bình thường lại là điều ta nhớ lâu.']]}
  ];
  function journal(){
    root.innerHTML=nav('The Journal.',[['#articles','Bài viết'],['#journal-note','Về tạp chí']])+`<main id="demo-main" class="demo-shell"><section class="journal-intro"><h1 class="demo-title">Ở đây, mình<br><em>chậm lại một chút.</em></h1><p>THOUGHTS ON DESIGN, LIVING & EVERYDAY LIFE.<br>ISSUE NO. 01 / 2026</p></section><section id="articles"><div class="journal-tools">${categories([['all','Tất cả'],['design','Thiết kế'],['living','Sống'],['stories','Câu chuyện']],'article-filter')}<label class="sr-only" for="article-search">Tìm bài viết</label><input class="search-input" id="article-search" type="search" placeholder="Tìm một câu chuyện…"></div><p class="sr-only" id="search-status" role="status"></p><div class="article-grid">${articles.map(a=>`<article class="article-card" data-article-category="${a.category}" data-article-id="${a.id}"><button data-read="${a.id}" aria-label="Đọc bài ${a.title}"><img src="../assets/${a.image}" alt="" loading="lazy"><div class="article-meta">${a.label} / ${a.time} PHÚT ĐỌC · BÀI VIẾT MẪU</div><h2>${a.title}</h2><p>${a.excerpt}</p><span class="read-link">Đọc câu chuyện ↗</span></button></article>`).join('')}</div><p class="empty-results" id="no-articles" hidden>Chưa tìm thấy câu chuyện phù hợp. Thử một từ khóa khác nhé.</p></section><section class="demo-section" id="journal-note"><p class="demo-kicker">A LITTLE SPACE FOR THE EVERYDAY.</p><h2>Những điều nhỏ,<br><em>đáng để nghĩ về.</em></h2><p class="demo-lead" style="margin-top:24px">The Journal là tạp chí concept. Những bài viết trong bản demo được sáng tác để minh họa cách tổ chức và trải nghiệm một blog cá nhân.</p></section></main>`;
    let active='all';
    const normalize=text=>text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/đ/g,'d');
    const filterArticles=()=>{const query=normalize(root.querySelector('#article-search').value.trim());let count=0;root.querySelectorAll('.article-card').forEach(card=>{const a=articles.find(a=>a.id===card.dataset.articleId);card.hidden=!(active==='all'||a.category===active)||!normalize(a.title+' '+a.excerpt).includes(query);if(!card.hidden)count++;});root.querySelector('#no-articles').hidden=count>0;root.querySelector('#search-status').textContent=`Tìm thấy ${count} bài viết.`;};
    root.querySelector('#article-search').addEventListener('input',filterArticles);
    root.querySelectorAll('[data-article-filter]').forEach(button=>button.addEventListener('click',()=>{active=button.dataset.articleFilter;tabState(root.querySelectorAll('[data-article-filter]'),button);filterArticles();}));
    root.querySelectorAll('[data-read]').forEach(button=>button.addEventListener('click',()=>{const a=articles.find(a=>a.id===button.dataset.read);open(`<article class="article-reading"><p class="article-meta">${a.label} / ${a.time} PHÚT ĐỌC · NỘI DUNG MẪU</p><h2 id="demo-dialog-title">${a.title}</h2><img src="../assets/${a.image}" alt="Hình minh họa bài viết"><p>${a.excerpt}</p>${a.body.map(([title,text])=>`<h3>${title}</h3><p>${text}</p>`).join('')}<button class="text-link" data-dismiss>Trở về những câu chuyện <span>↗</span></button></article>`);}));
  }

  const dashboardData={
    week:{name:'7 ngày',revenue:32400000,orders:324,customers:216,conversion:'3,2%',labels:['T2','T3','T4','T5','T6','T7','CN'],values:[2.8,4.2,3.5,5.7,4.1,6.9,5.2]},
    month:{name:'30 ngày',revenue:128400000,orders:1284,customers:856,conversion:'3,8%',labels:['01','05','10','15','20','25','30'],values:[10,16,12,23,18,28,21.4]},
    quarter:{name:'90 ngày',revenue:386500000,orders:3865,customers:2576,conversion:'4,1%',labels:['Tuần 1','3','5','7','9','11','13'],values:[31,48,39,64,51,82,71.5]}
  };
  function pulse(){
    root.innerHTML=`<main id="demo-main" class="dashboard-layout"><aside class="dashboard-sidebar"><a class="demo-brand" href="?project=pulse">pulse<span style="color:#7c9d49">.</span></a><p>WORKSPACE DEMO</p><a class="active" href="#overview">◫ &nbsp; Tổng quan</a><a href="#analytics">⌁ &nbsp; Phân tích</a><a href="#orders">▤ &nbsp; Đơn hàng</a><a href="#products">◈ &nbsp; Sản phẩm</a><p>Một cửa hàng giả lập.<br>Dữ liệu chỉ để minh họa.</p></aside><div class="dashboard-content"><header class="dashboard-header" id="overview"><div><h1>Tổng quan cửa hàng</h1><p>Một góc nhìn rõ ràng hơn về dữ liệu kinh doanh mẫu.</p></div><div class="dashboard-range" role="group" aria-label="Khoảng thời gian">${[['week','7 ngày'],['month','30 ngày'],['quarter','90 ngày']].map(([id,label])=>`<button data-range="${id}" class="${id==='month'?'active':''}" aria-pressed="${id==='month'}">${label}</button>`).join('')}</div></header><div class="metric-grid" id="metrics" aria-live="polite"></div><div class="dashboard-panels"><section class="dashboard-panel" id="analytics"><h2>Phân tích doanh thu</h2><p id="chart-caption">Doanh thu theo kỳ — dữ liệu mẫu</p><div class="revenue-chart" id="revenue-chart"></div></section><section class="dashboard-panel" id="products"><h2>Danh mục nổi bật</h2><p>Tỷ trọng doanh thu mẫu</p>${[['Nội thất',62],['Đồ dùng',24],['Trang trí',14]].map(([label,n])=>`<div class="sales-row"><div><span>${label}</span><span>${n}%</span></div><progress value="${n}" max="100" aria-label="${label}: ${n}%"></progress></div>`).join('')}</section></div><section class="dashboard-panel orders-panel" id="orders"><div class="orders-heading"><h2>Đơn hàng gần đây</h2><button id="export-csv">↓ Xuất báo cáo CSV</button></div><div class="table-scroll"><table><caption class="sr-only">Danh sách đơn hàng mô phỏng</caption><thead><tr><th>Mã đơn</th><th>Khách hàng mẫu</th><th>Sản phẩm</th><th>Giá trị</th><th>Trạng thái</th></tr></thead><tbody>${[['DEMO-1024','Khách hàng A','Lounge Chair',3250000,'Hoàn thành'],['DEMO-1023','Khách hàng B','Coffee Set',480000,'Đang xử lý'],['DEMO-1022','Khách hàng C','Living Set',8900000,'Hoàn thành'],['DEMO-1021','Khách hàng D','Morning Ritual',650000,'Hoàn thành'],['DEMO-1020','Khách hàng E','Lounge Chair / Soft',3650000,'Đang xử lý']].map(([id,name,item,price,status])=>`<tr><td>${id}</td><td>${name}</td><td>${item}</td><td>${money(price)}</td><td><span class="order-status ${status==='Đang xử lý'?'pending':''}">${status}</span></td></tr>`).join('')}</tbody></table></div></section></div></main>`;
    let range='month';
    const render=()=>{const d=dashboardData[range];root.querySelector('#metrics').innerHTML=[['Doanh thu',money(d.revenue),'12,8'],['Đơn hàng',new Intl.NumberFormat('vi-VN').format(d.orders),'8,2'],['Khách hàng',new Intl.NumberFormat('vi-VN').format(d.customers),'6,4'],['Tỷ lệ chuyển đổi',d.conversion,'2,1']].map(([label,value,growth])=>`<article class="metric"><span>${label}</span><strong>${value}</strong><small>↗ ${growth}% so với kỳ mẫu trước</small></article>`).join('');
      const max=Math.ceil(Math.max(...d.values)/10)*10;const width=480,height=200,barWidth=32;const step=width/d.values.length;
      root.querySelector('#chart-caption').textContent=`${d.name} · Đơn vị: triệu đồng · Dữ liệu mô phỏng`;
      root.querySelector('#revenue-chart').innerHTML=`<svg viewBox="0 0 520 240" role="img" aria-labelledby="chart-title chart-description"><title id="chart-title">Doanh thu mẫu trong ${d.name}</title><desc id="chart-description">${d.labels.map((label,i)=>`${label}: ${d.values[i]} triệu đồng`).join('; ')}</desc>${[0,1,2,3,4].map(i=>`<line x1="35" y1="${20+i*45}" x2="515" y2="${20+i*45}" stroke="#eaf0df"/><text x="0" y="${24+i*45}" class="chart-axis">${Math.round(max*(1-i/4))}M</text>`).join('')}${d.values.map((value,i)=>{const h=value/max*(height-20);const x=35+i*step+(step-barWidth)/2;return `<rect x="${x}" y="${height-h}" width="${barWidth}" height="${h}" rx="4" fill="${i===d.values.length-2?'#425d35':'#bfd3a4'}"><title>${d.labels[i]}: ${value} triệu đồng</title></rect><text class="chart-axis" text-anchor="middle" x="${x+barWidth/2}" y="224">${d.labels[i]}</text>`;}).join('')}</svg>`;
    };
    root.querySelectorAll('[data-range]').forEach(button=>button.addEventListener('click',()=>{range=button.dataset.range;tabState(root.querySelectorAll('[data-range]'),button);render();}));
    root.querySelector('#export-csv').addEventListener('click',()=>{const d=dashboardData[range];const csv='\ufeffKỳ mẫu,Doanh thu (triệu VND)\r\n'+d.labels.map((label,i)=>`${label},${d.values[i]}`).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`pulse-doanh-thu-${range}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã xuất báo cáo doanh thu mẫu.');});
    render();
  }

  const destinations=[{id:'mountain',label:'Núi & hồ',name:'Một sớm giữa núi',image:'coast.jpg',price:1850000,group:'nature',description:'Một căn nghỉ nhỏ, mặt hồ yên và những buổi sáng không cần báo thức.'},{id:'retreat',label:'Không gian nghỉ',name:'Ở trong một khoảng xanh',image:'interior.jpg',price:2150000,group:'retreat',description:'Ánh sáng tự nhiên, một chiếc ghế thật êm và cả ngày dành cho riêng bạn.'},{id:'city',label:'Khám phá thành phố',name:'Góc phố chưa quen',image:'architecture.jpg',price:1450000,group:'city',description:'Đi bộ qua những góc nhỏ, gặp một quán mới và nhìn thành phố bằng đôi mắt khác.'}];
  function escape(){
    root.innerHTML=nav('escape.',[['#destinations','Điểm đến'],['#travel-story','Tinh thần Escape']],'<a class="nav-action" href="#search-trip">Lên đường ↗</a>')+`<main id="demo-main"><section class="travel-hero"><p class="demo-kicker">GO SOMEWHERE THAT FEELS LIKE YOU.</p><h1 class="demo-title">Somewhere<br><em>you belong.</em></h1><p>Rời những quen thuộc. Tìm những bình yên.</p></section><form class="travel-search demo-shell" id="search-trip"><label>BẠN MUỐN ĐI ĐÂU?<select name="destination"><option value="all">Mọi điểm đến</option><option value="nature">Núi & hồ</option><option value="retreat">Nghỉ dưỡng</option><option value="city">Thành phố</option></select></label><label>NGÀY KHỞI HÀNH<input name="date" type="date" min="${localDate()}" value="${localDate(7)}" required></label><label>SỐ KHÁCH<select name="guests"><option value="1">1 khách</option><option value="2" selected>2 khách</option><option value="3">3 khách</option><option value="4">4 khách</option></select></label><button class="button dark" type="submit">Tìm chốn nghỉ <span>↗</span></button></form><section class="demo-section demo-shell" id="destinations"><div class="demo-section-heading"><h2>Đi theo điều bạn thích.</h2><p id="destination-status" role="status">3 gợi ý trải nghiệm concept.</p></div><div class="destination-grid">${destinations.map(d=>`<article class="destination-card" data-destination-group="${d.group}"><img src="../assets/${d.image}" alt="${d.name}" loading="lazy"><div class="destination-body"><span>${d.label.toUpperCase()}</span><h3>${d.name}</h3><p>${d.description}</p><div class="destination-bottom"><span>${money(d.price)}<small> / đêm</small></span><button data-book="${d.id}">Khám phá ↗</button></div></div></article>`).join('')}</div><p class="travel-note">Điểm nghỉ và giá đều là ví dụ minh họa. Không đại diện cho cơ sở lưu trú hoặc giá bán thực tế.</p></section><section class="demo-section demo-shell" id="travel-story"><p class="demo-kicker">LESS ITINERARY. MORE FEELING.</p><h2>Chuyến đi của bạn.<br><em>Nhịp điệu của bạn.</em></h2><p class="demo-lead" style="margin-top:25px">Escape là một ý tưởng về du lịch chậm. Thay vì lấp đầy lịch trình, hãy để lại một chút khoảng trống cho những điều bất ngờ dễ chịu.</p></section></main>`;
    const search=root.querySelector('#search-trip');
    search.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(search);let count=0;root.querySelectorAll('[data-destination-group]').forEach(card=>{card.hidden=data.get('destination')!=='all'&&card.dataset.destinationGroup!==data.get('destination');if(!card.hidden)count++;});root.querySelector('#destination-status').textContent=`${count} gợi ý · ${data.get('date').split('-').reverse().join('/')} · ${data.get('guests')} khách`;root.querySelector('#destinations').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});});
    root.querySelectorAll('[data-book]').forEach(button=>button.addEventListener('click',()=>{
      const d=destinations.find(d=>d.id===button.dataset.book);const data=new FormData(search);
      open(`<h2 id="demo-dialog-title">${d.name}</h2><p class="detail-description">Tạo yêu cầu đặt chỗ mẫu. Thông tin không được gửi đến cơ sở lưu trú.</p><form class="demo-dialog-form" id="booking-form"><label>Tên của bạn<input name="name" required maxlength="100" autocomplete="name" placeholder="Tên của bạn"></label><label>Email<input name="email" type="email" required autocomplete="email" placeholder="ban@example.com"></label><label>Ngày đến<input name="date" type="date" min="${localDate()}" value="${safe(data.get('date'))}" required></label><label>Số đêm<select name="nights"><option value="1">1 đêm</option><option value="2" selected>2 đêm</option><option value="3">3 đêm</option><option value="5">5 đêm</option></select></label><label>Số khách<select name="guests">${[1,2,3,4].map(n=>`<option value="${n}" ${String(n)===data.get('guests')?'selected':''}>${n} khách</option>`).join('')}</select></label><p id="booking-estimate">Tổng giá minh họa: <strong>${money(d.price*2)}</strong> / phòng.</p><button class="button dark" type="submit">Tạo yêu cầu mẫu <span>↗</span></button></form>`);
      const form=modalContent.querySelector('#booking-form');form.querySelector('[name="nights"]').addEventListener('change',e=>{form.querySelector('#booking-estimate').innerHTML=`Tổng giá minh họa: <strong>${money(d.price*Number(e.target.value))}</strong> / phòng.`;});
      form.addEventListener('submit',e=>{e.preventDefault();const booking=new FormData(form);confirmation('Một chuyến đi đang chờ.',`Brief đặt chỗ mẫu cho <strong>${d.name}</strong>, ngày ${safe(booking.get('date').split('-').reverse().join('/'))}, ${safe(booking.get('nights'))} đêm, ${safe(booking.get('guests'))} khách. Tổng giá mẫu: ${money(d.price*Number(booking.get('nights')))}.`);});
    }));
  }

  function moka(){
    products=[{id:'latte',name:'Latte buổi sáng',price:58000,group:'coffee',image:'coffee.jpg',description:'Espresso, sữa tươi và một lớp bọt mịn.'},{id:'black',name:'Cà phê đen',price:42000,group:'coffee',image:'coffee.jpg',description:'Đơn giản. Đậm đà. Đúng nhịp của bạn.'},{id:'salad',name:'Salad khu vườn',price:98000,group:'food',image:'food.jpg',description:'Rau tươi, một chút giòn và sốt nhà làm.'},{id:'bowl',name:'Brunch bowl',price:125000,group:'food',image:'food.jpg',description:'Một bữa nhẹ đầy màu sắc cho ngày mới.'},{id:'brew',name:'Cold brew',price:62000,group:'coffee',image:'coffee.jpg',description:'Êm, mát và thong thả hơn một chút.'},{id:'seasonal',name:'Đĩa rau theo mùa',price:85000,group:'food',image:'food.jpg',description:'Những hương vị giản dị trên cùng một đĩa.'}];
    root.innerHTML=`<div class="restaurant-top">${nav('moka.',[['#menu','Thực đơn'],['#our-story','Câu chuyện']],'<button class="nav-action" data-cart>Giỏ món (<span data-cart-count>0</span>)</button>')}<main id="demo-main"><section class="demo-hero demo-shell"><div><p class="demo-kicker">COFFEE. COMFORT. GOOD COMPANY.</p><h1 class="demo-title">Slow mornings.<br><em>Good coffee.</em></h1><p class="demo-lead">Một chỗ ngồi quen. Một mùi hương dễ chịu. Một chút thời gian cho những câu chuyện chưa kịp kể.</p><a class="restaurant-button" href="#menu">Khám phá thực đơn ↗</a></div><img class="demo-hero-image" src="../assets/coffee.jpg" alt="Cà phê cho một buổi sáng thong thả" fetchpriority="high"></section></main></div><section class="demo-section demo-shell" id="menu"><div class="demo-section-heading"><h2>Made slow. Served warm.</h2><p>Một thực đơn concept, đầy những điều quen.</p></div>${categories([['all','Tất cả'],['coffee','Cà phê'],['food','Bếp nhỏ']],'menu-filter')}<div class="menu-grid">${products.map(p=>`<article class="menu-item" data-menu-group="${p.group}"><img src="../assets/${p.image}" alt="${p.name}" loading="lazy"><div class="product-details"><div><h3>${p.name}</h3><p>${p.description}</p><span class="menu-price">${money(p.price)}</span></div><button class="add-product" data-add="${p.id}" aria-label="Thêm ${p.name}">+</button></div></article>`).join('')}</div><p class="travel-note">Món ăn và giá chỉ để minh họa trải nghiệm.</p></section><section class="demo-section demo-shell"><div class="restaurant-story" id="our-story"><img src="../assets/interior.jpg" alt="Không gian ấm áp, ánh sáng tự nhiên" loading="lazy"><div><p class="demo-kicker">COME AS YOU ARE.</p><h2>Một nơi để<br><em>ngồi lại.</em></h2><p>Moka là một quán cà phê và bistro concept, lấy cảm hứng từ những buổi sáng không vội và những cuộc hẹn rất đỗi bình thường.</p><p>Không cần một dịp đặc biệt. Một chiếc bàn nhỏ và một câu chuyện là đủ.</p><a class="text-link" href="#reservation">Thử đặt một chiếc bàn <span>↗</span></a></div></div><div class="reservation" id="reservation"><h2>Một chiếc bàn cho bạn.</h2><p>Biểu mẫu đặt bàn minh họa. Không có lịch đặt thực tế hoặc yêu cầu được gửi đến nhà hàng.</p><form id="reservation-form"><label>Tên của bạn<input name="name" autocomplete="name" required maxlength="100" placeholder="Tên của bạn"></label><label>Email<input name="email" type="email" autocomplete="email" required placeholder="ban@example.com"></label><label>Ngày hẹn<input name="date" type="date" min="${localDate()}" value="${localDate(1)}" required></label><label>Giờ hẹn<select name="time"><option>08:00</option><option>10:00</option><option selected>14:00</option><option>16:00</option><option>18:00</option></select></label><label>Số người<select name="guests"><option>1 người</option><option selected>2 người</option><option>3 người</option><option>4 người</option><option>5 người</option><option>6 người</option></select></label><button class="button dark" type="submit">Tạo đặt bàn mẫu <span>↗</span></button><p class="form-status" id="reservation-status" role="status"></p></form></div></section>`;
    root.querySelectorAll('[data-menu-filter]').forEach(button=>button.addEventListener('click',()=>{tabState(root.querySelectorAll('[data-menu-filter]'),button);root.querySelectorAll('[data-menu-group]').forEach(card=>card.hidden=button.dataset.menuFilter!=='all'&&card.dataset.menuGroup!==button.dataset.menuFilter);}));
    root.querySelector('#reservation-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);confirmation('Hẹn một buổi thật chậm.',`Đặt bàn mẫu cho ${safe(data.get('name'))}, ${safe(data.get('guests'))}, lúc ${safe(data.get('time'))} ngày ${safe(data.get('date').split('-').reverse().join('/'))}.`);root.querySelector('#reservation-status').textContent='Đã tạo đặt bàn mẫu. Chưa có thông tin được gửi đến người nhận.';});
  }

  ({objects,orbit,journal,pulse,escape,moka})[key]();
})();
